<?php
require_once __DIR__.'/config/auth.php';
refresh_cart_prices();
$cart=$_SESSION['cart']??[];if(!$cart){header('Location: '.BASE_URL.'/cart.php');exit;}
$error='';$successOrder=null;$promoCode='';$tableId=table_id_from_qr();
$tables=dbq('SELECT id,nomor_meja FROM `tables` ORDER BY nomor_meja')->fetchAll();
function active_promo(PDO $pdo,string $code,float $subtotal): array|false {
 $st=$pdo->prepare("SELECT p.*,(SELECT COUNT(*) FROM promo_usages pu WHERE pu.promo_id=p.id) AS used FROM promos p WHERE p.kode=? AND p.is_active=1 AND (p.mulai IS NULL OR p.mulai<=NOW()) AND (p.selesai IS NULL OR p.selesai>=NOW()) LIMIT 1");$st->execute([strtoupper(trim($code))]);$p=$st->fetch();if(!$p||(int)$p['kuota']>0&&(int)$p['used'] >= (int)$p['kuota']||$subtotal<(float)$p['min_belanja'])return false;return $p;
}
$subtotal=cart_subtotal();$previewDiscount=0;
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();$name=clean_text((string)($_POST['nama_pelanggan']??''),100);$tableId=(int)($_POST['table_id']??0);$method=(string)($_POST['metode_bayar']??'Kasir');$promoCode=strtoupper(trim((string)($_POST['kode_promo']??'')));$customerNote=clean_text((string)($_POST['catatan']??''),800);
 if($name==='')$error='nama pelanggan wajib diisi.';
 elseif(!in_array($method,['Kasir','QRIS'],true))$error='metode pembayaran tidak valid.';
 elseif($tableId>0&&!in_array($tableId,array_column($tables,'id'))) $error='nomor meja tidak valid.';
 else {
  $promo=false;$discount=0;
  if($promoCode!==''){$promo=active_promo($pdo,$promoCode,$subtotal);if(!$promo)$error='kode promo tidak valid, sudah habis, atau belum memenuhi minimal belanja.';else $discount=($promo['tipe']==='persen')?min($subtotal,$subtotal*(float)$promo['nilai']/100):min($subtotal,(float)$promo['nilai']);}
  if(!$error){
   $taxPercent=max(0,(float)get_setting('tax_percent','0'));$servicePercent=max(0,(float)get_setting('service_percent','0'));$tax=round(max(0,$subtotal-$discount)*$taxPercent/100);$service=round(max(0,$subtotal-$discount)*$servicePercent/100);$total=max(0,$subtotal-$discount)+$tax+$service;
   try{$pdo->beginTransaction();
    if($promo){$lock=$pdo->prepare('SELECT id,kuota FROM promos WHERE id=? AND is_active=1 FOR UPDATE');$lock->execute([(int)$promo['id']]);$live=$lock->fetch();$count=$pdo->prepare('SELECT COUNT(*) FROM promo_usages WHERE promo_id=?');$count->execute([(int)$promo['id']]);if(!$live || ((int)$live['kuota']>0 && (int)$count->fetchColumn()>=(int)$live['kuota']))throw new RuntimeException('kuota promo baru saja habis.');}
    foreach($cart as $it){$check=$pdo->prepare('SELECT stok,is_available,nama,harga FROM menus WHERE id=? FOR UPDATE');$check->execute([(int)$it['menu_id']]);$live=$check->fetch();if(!$live||!(int)$live['is_available']||(int)$live['stok']<(int)$it['qty'])throw new RuntimeException('stok menu '.($live['nama']??$it['name']).' tidak mencukupi.');}
    $code=random_order_code();$payStatus=$method==='QRIS'?'Menunggu QRIS':'Belum Bayar';$catatan=$customerNote;
    if($promo)$catatan=trim($catatan.' | Promo: '.$promoCode,' |');
    $ins=$pdo->prepare('INSERT INTO orders (kode_pesanan,nama_pelanggan,table_id,subtotal,diskon,pajak,total,metode_bayar,status_bayar,status_pesanan,catatan) VALUES (?,?,?,?,?,?,?,?,?,?,?)');$ins->execute([$code,$name,$tableId?:null,$subtotal,$discount,$tax+$service,$total,$method,$payStatus,'Diterima',$catatan]);$orderId=(int)$pdo->lastInsertId();
    $itemIns=$pdo->prepare('INSERT INTO order_items (order_id,menu_id,nama_menu,qty,harga,opsi_json,catatan) VALUES (?,?,?,?,?,?,?)');$stock=$pdo->prepare('UPDATE menus SET stok=stok-? WHERE id=?');
    foreach($cart as $it){$itemIns->execute([$orderId,(int)$it['menu_id'],$it['name'],(int)$it['qty'],(float)$it['price'],json_encode($it['options'],JSON_UNESCAPED_UNICODE),$it['note']??'']);$stock->execute([(int)$it['qty'],(int)$it['menu_id']]);}
    if($promo){$pu=$pdo->prepare('INSERT INTO promo_usages (promo_id,order_id) VALUES (?,?)');$pu->execute([(int)$promo['id'],$orderId]);}
    $pdo->commit();$_SESSION['cart']=[];$_SESSION['last_order_code']=$code;$successOrder=$code;
   }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'pesanan gagal disimpan. coba lagi.';}
  }
 }
}
if($successOrder){header('Location: '.BASE_URL.'/track.php?kode='.urlencode($successOrder).'&baru=1');exit;}
$promoPreview=$promoCode!==''?active_promo($pdo,$promoCode,$subtotal):false;if($promoPreview)$previewDiscount=($promoPreview['tipe']==='persen')?min($subtotal,$subtotal*(float)$promoPreview['nilai']/100):min($subtotal,(float)$promoPreview['nilai']);
$pageTitle='Checkout';require __DIR__.'/includes/header.php'; ?>
<section class="max-w-5xl mx-auto px-4 py-10"><p class="section-kicker">satu langkah lagi</p><h1 class="font-serif text-4xl mt-2">checkout</h1><p class="text-sm text-coffee/60 mt-2">isi detail pesananmu. kamu tidak perlu membuat akun.</p><?php if($error):?><div class="flash flash-error"><?= h($error) ?></div><?php endif;?>
<form method="post" class="grid lg:grid-cols-[1fr_340px] gap-6 mt-7"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><div class="card p-5 sm:p-7 space-y-5"><div><label class="field-label" for="nama">nama pelanggan</label><input class="field" id="nama" name="nama_pelanggan" maxlength="100" value="<?= h($_POST['nama_pelanggan']??'') ?>" required placeholder="nama kamu"></div><div><label class="field-label" for="meja">nomor meja</label><select class="field" id="meja" name="table_id"><option value="0">Take away / belum pilih meja</option><?php foreach($tables as $t):?><option value="<?= (int)$t['id'] ?>" <?= (int)$tableId===(int)$t['id']?'selected':'' ?>>Meja <?= h($t['nomor_meja']) ?></option><?php endforeach;?></select></div><div><label class="field-label">metode pembayaran</label><div class="grid sm:grid-cols-2 gap-3"><label class="border border-coffee/15 rounded-2xl p-4 flex gap-3"><input type="radio" class="accent-[#8A9A5B] mt-1" name="metode_bayar" value="Kasir" <?= ($_POST['metode_bayar']??'Kasir')==='Kasir'?'checked':'' ?>><span><b class="block text-sm">Bayar di kasir</b><small class="block text-xs mt-1 text-coffee/60">tunai atau QRIS di kasir</small></span></label><label class="border border-coffee/15 rounded-2xl p-4 flex gap-3"><input type="radio" class="accent-[#8A9A5B] mt-1" name="metode_bayar" value="QRIS" <?= ($_POST['metode_bayar']??'')==='QRIS'?'checked':'' ?>><span><b class="block text-sm">QRIS</b><small class="block text-xs mt-1 text-coffee/60">menunggu konfirmasi kasir</small></span></label></div><p class="text-xs text-coffee/55 mt-2"><?= h(get_setting('qris_info','Pembayaran QRIS dikonfirmasi oleh kasir.')) ?></p></div><div><label class="field-label" for="promo">kode promo (opsional)</label><input class="field uppercase" id="promo" name="kode_promo" value="<?= h($promoCode) ?>" placeholder="mis. NGOPI10"></div><div><label class="field-label" for="catatan">catatan pesanan (opsional)</label><textarea class="field" id="catatan" name="catatan" rows="2" maxlength="800" placeholder="permintaan khusus..."><?= h($_POST['catatan']??'') ?></textarea></div></div>
<aside class="card p-5 h-fit"><h2 class="font-serif text-2xl">ringkasan</h2><div class="mt-4 space-y-3"><?php foreach($cart as $item):?><div class="flex justify-between gap-3 text-sm"><span><?= (int)$item['qty'] ?>× <?= h($item['name']) ?></span><span class="whitespace-nowrap"><?= money($item['price']*$item['qty']) ?></span></div><?php endforeach;?></div><div class="border-t border-coffee/10 my-4"></div><div class="flex justify-between text-sm"><span>Subtotal</span><span><?= money($subtotal) ?></span></div><?php if($previewDiscount):?><div class="flex justify-between text-sm text-green-800 mt-2"><span>Promo</span><span>-<?= money($previewDiscount) ?></span></div><?php endif;?><div class="flex justify-between text-sm mt-2"><span>Pajak/service</span><span>dihitung saat proses</span></div><div class="flex justify-between font-bold border-t border-coffee/10 mt-4 pt-4"><span>Estimasi total</span><span><?= money($subtotal-$previewDiscount) ?>+</span></div><button class="btn btn-coffee w-full mt-5" type="submit">Buat Pesanan →</button><p class="text-xs text-center text-coffee/55 mt-3">dengan melanjutkan, pesanan akan dikirim ke kasir.</p></aside></form></section>
<?php require __DIR__.'/includes/footer.php'; ?>
